package com.savora.config;
import com.savora.security.JwtFilter; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter jwt)throws Exception{return h.csrf(c->c.disable()).cors(c->c.configurationSource(r->{var x=new CorsConfiguration();x.setAllowedOriginPatterns(java.util.List.of("http://localhost:*"));x.setAllowedMethods(java.util.List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));x.setAllowedHeaders(java.util.List.of("*"));x.setAllowCredentials(true);return x;})).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/auth/**","/restaurants/**","/foods/**","/categories/**","/home","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers("/admin/**").hasRole("ADMIN").requestMatchers("/orders/**").authenticated().anyRequest().denyAll()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
